async (t) => {
  const local = await localFabric(t, { sleepSeconds: WATCHED_SYNTH_SECONDS });
  if (!local) return;
  const { h, host, dispose } = local;
  let sessions: string[] = [];
  try {
    // Left running while the Run is asked about, because every meter but one reads differently on a
    // Campaign that has stopped: the seat is released, the generation's clock has stopped, and no
    // node is part way through an attempt.
    const running = inBackground(host, h, `/hima run ${timingProbePackId} --site local --goal target_period_ns=2.0 --set periodNs=2.0 --time-box 5 --retries 2 ${ONE_GENERATION}`);
    const open = await launchedJobOf(host);
    sessions = sessionsOf(host, open.runId);
    // The `launched` record lands before the meters that count it: the turn writes the Job, then the
    // node's `running` record, then moves the row. Asked in that window, the row still says no Job
    // was launched — which the pre-push suite saw once under load — so the meters are waited for.
    await waitUntil('the row counts the launch', () => runOf(host, open.runId).meters?.jobsLaunched === 1, 10_000);

    const status = await himaCommand(host, h.workspace, `/hima status ${open.runId}`);
    for (const line of status.text.split('\n')) t.diagnostic(line);
    assert.equal(status.kind, 'success', status.text);

    // What the row holds, which is exactly what `GET /hima/api/runs/<id>` answers with as `budget`
    // and `meters` — the run view copies both from the row — so these are the numbers the lines
    // below have to be saying.
    const run = runOf(host, open.runId);
    assert.equal(run.status, 'running', `the Run is still going while it is asked about: ${JSON.stringify(run)}`);
    assert.equal(run.budget?.timeBoxMs, 5 * 60_000, JSON.stringify(run.budget));
    assert.equal(run.budget?.generationLimit, 1, JSON.stringify(run.budget));
    assert.equal(run.budget?.jobCap, 1, JSON.stringify(run.budget));
    assert.equal(run.budget?.retryAllowance, 2, JSON.stringify(run.budget));
    assert.deepEqual(run.budget?.licences, { [STANDIN_LICENCE]: 1 }, JSON.stringify(run.budget));
    assert.equal(run.meters?.jobsLaunched, 1, JSON.stringify(run.meters));
    assert.equal(run.generation, 1, JSON.stringify(run));

    // One line per meter, each against the bound above it in the row.
    assert.match(status.text, /^ {4}elapsed \d[\d.]* (?:ms|s|min) of a time box of 5\.0 min$/m, status.text);
    assert.match(status.text, /^ {4}generation 1 of at most 1, \d[\d.]* (?:ms|s|min)$/m, status.text);
    assert.match(status.text, /^ {4}1 job launched, at most 1 job at a time$/m, status.text);
    assert.match(status.text, /^ {4}synthesize: attempt 1 of a retry allowance of 2, and 1 attempt in the campaign so far$/m, status.text);
    assert.match(status.text, /^ {4}Design-Compiler 1 seat of 1 declared$/m, `the seat is held while the job runs: ${status.text}`);
    assert.doesNotMatch(status.text, /^ {4}ended by /m, `nothing has ended this Run: ${status.text}`);

    // And the same command once it has stopped: the seat is back, and the meter that ended it is
    // named in words rather than in the ledger's own key.
    const ran = await running.done;
    assert.equal(ran.kind, 'success', ran.text);
    assert.match(ran.text, /^ {4}Design-Compiler 0 seats of 1 declared, held for \d[\d.]* (?:ms|s|min)$/m, ran.text);
    assert.match(ran.text, /^ {4}ended by the generation limit$/m, ran.text);
  } finally {
    killSessions(sessions);
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t, { sleepSeconds: 1, failures: 1 });
  if (!local) return;
  const { h, host, dispose } = local;
  let sessions: string[] = [];
  try {
    const packsDir = packsDirOf(h);
    const pack = await installDrillDown(packsDir, 'drill-down', 6);

    // No retry allowance and a flow that fails once: the loop's first synthesis is a Hard blocker at
    // once, and the Run is routed to the wait node the *graph* declares, because this loop declares
    // none. The loop stays open on the row while a person is asked, which is what the run line says.
    const started = await himaCommand(
      host,
      h.workspace,
      `/hima run ${pack} --site local --goal target_period_ns=2.0 --set periodNs=2.0 --retries 0`,
      siteCommandTimeoutMs,
    );
    const runId = started.runId;
    assert.ok(runId, started.text);
    sessions = sessionsOf(host, runId);
    const status = await himaCommand(host, h.workspace, `/hima status ${runId}`);
    assert.equal(status.kind, 'success', status.text);
    assert.match(status.text, /: waiting, generation 1 of at most 6, in loop push at generation 1$/m, `the run line says which loop it is inside: ${status.text}`);
    assert.match(status.text, /^ {2}current node: blocked$/m, `and that it waits at the graph's own wait node: ${status.text}`);

    // An explore node that names a chooser and opens a loop: two different things for one node to be,
    // refused when the pack is loaded — which is how every other way a pack can contradict itself is
    // refused, and which a person meets as the load's own message.
    await writePackVariant(packsDir, 'chooses-and-opens', []);
    await writeFile(
      path.join(packsDir, 'chooses-and-opens', 'graph.yml'),
      drillDownGraph('chooses-and-opens', 6).replace('      opens: push\n', '      opens: push\n      chooser: timing-push\n'),
    );
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check chooses-and-opens --site local'),
      /gives explore node "probe" both chooser "timing-push" and `opens: push`: an explore node either applies a chooser and decides, or opens a loop and drills down, and states exactly one of the two/,
      'the refusal names the node and what an explore node may be',
    );

    // A loop whose own explore node opens a loop: drill-down goes one level in step 3, and a pack
    // that asks for two is refused where the file can still be read.
    await writePackVariant(packsDir, 'opens-twice', []);
    await writeFile(
      path.join(packsDir, 'opens-twice', 'graph.yml'),
      drillDownGraph('opens-twice', 6).replace('          chooser: over-constraining-push\n', '          opens: push\n'),
    );
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check opens-twice --site local'),
      /has explore node "next-period" of loop "push" open loop "push": a loop's explore node applies a chooser, because drill-down goes one level and no further/,
      'the refusal names the node, its loop, and why there is no second level',
    );
  } finally {
    killSessions(sessions);
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t, {});
  if (!local) return;
  const { h, host, dispose } = local;
  try {
    const packsDir = packsDirOf(h);
    /** The drill-down graph with one thing about it changed, installed under its own id. */
    const variant = async (id: string, change: (graph: string) => string): Promise<void> => {
      await writePackVariant(packsDir, id, []);
      await writeFile(path.join(packsDir, id, 'graph.yml'), change(drillDownGraph(id, 6)));
    };

    // An edge out of the opening explore node with no outcome on it. It loads as a route a person
    // would read in the file — probe leads to final-read — and the engine, which leaves that node
    // only on the edge its loop's outcome labels, would never take it: the loop would close and the
    // Run would end as though the node drew no edge at all.
    await variant('unlabelled-outcome', (g) => g.replace('  - { from: probe, to: final-read, outcome: converged }\n', '  - { from: probe, to: final-read }\n'));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check unlabelled-outcome --site local'),
      /draws an edge in its graph from explore node "probe" to "final-read" with no outcome on it: that node opens a loop and is left on the edge its loop closed with, so every edge out of it carries one of "goal-met", "converged", "generation-limit"/,
      'the refusal names the node, the edge, and the three outcomes an opening node\'s edges carry',
    );

    // A revisit edge out of the opening explore node. That node revisits nothing itself — the loop
    // it opens carries its own revisit edge — so a `revisit: true` here is a way back the file shows
    // and the engine never takes.
    await variant('probe-revisits', (g) => g.replace('  - { from: probe, to: final-read, outcome: converged }', '  - { from: probe, to: final-read, outcome: converged, revisit: true }'));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check probe-revisits --site local'),
      /gives explore node "probe" in its graph a revisit edge to "final-read": an explore node that opens a loop revisits nothing itself/,
      'the refusal names the node, where its revisit edge leads, and why an opening node revisits nothing',
    );

    // Two edges out of one node labelled the same. The engine takes the first that matches, so which
    // of them a converged loop leads along would be the order the lines happen to be written in.
    await variant('two-converged', (g) => g.replace('  - { from: probe, to: blocked, outcome: generation-limit }', '  - { from: probe, to: blocked, outcome: converged }'));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check two-converged --site local'),
      /draws two edges in its graph out of "probe" labelled "converged", to "final-read" and to "blocked": one outcome leads one way/,
      'the refusal names the node, the label, and both places it leads',
    );

    // Two wait nodes in one graph. Nothing draws an edge to a wait node — the engine routes a Hard
    // blocker there — so a graph declaring two says nothing about which one a person is sent to.
    await variant('two-wait-nodes', (g) => g.replace('\nedges:\n  - { from: probe', '\n  - id: also-blocked\n    kind: wait\n    parameters:\n      blocker: hard-blocker\n\nedges:\n  - { from: probe'));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check two-wait-nodes --site local'),
      /declares 2 wait nodes in its graph, "blocked" and "also-blocked": a graph declares at most one/,
      'the refusal names both wait nodes',
    );
  } finally {
    await dispose();
  }
}

async (t) => {
  // No retry allowance and a second branch whose flow fails once: that branch is a Hard blocker at
  // its first attempt while the first branch runs to the join, so the Run waits with the fork open —
  // which is the shape a person asks `/hima status` about.
  const local = await localFabric(t, { sleepSeconds: 1, failuresByTag: { b: 1 }, parallelJobs: 2, licences: { 'Design-Compiler': 2 } });
  if (!local) return;
  const { h, host, dispose } = local;
  let sessions: string[] = [];
  try {
    const pack = await installFork(packsDirOf(h), 'fork-join-status', 2.2);
    const started = await himaCommand(
      host,
      h.workspace,
      `/hima run ${pack} --site local --goal target_period_ns=2.0 --set periodNs=2.0 --retries 0`,
      siteCommandTimeoutMs,
    );
    const runId = started.runId;
    assert.ok(runId, started.text);
    sessions = sessionsOf(host, runId);

    const status = await himaCommand(host, h.workspace, `/hima status ${runId}`);
    assert.equal(status.kind, 'success', status.text);
    assert.match(
      status.text,
      /: waiting, generation 1 of at most 6, in the fork at start waiting at judge for 2 branches$/m,
      `the run line says which fork it is inside and what it is waiting for: ${status.text}`,
    );
    assert.match(status.text, /^ {2}current node: judge$/m, `and that it stands at the join: ${status.text}`);
    assert.match(status.text, /^ {2}branches:\n {4}synthesize: done, 1 job\n {4}synth-b: blocked, 1 job$/m, `and lists each branch and what it is doing: ${status.text}`);
  } finally {
    killSessions(sessions);
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t, {});
  if (!local) return;
  const { h, host, dispose } = local;
  try {
    const packsDir = packsDirOf(h);
    /** The forking graph with one thing about it changed, installed under its own id. */
    const variant = async (id: string, change: (graph: string) => string): Promise<void> => {
      await installFork(packsDir, id, 2.2);
      await writeFile(path.join(packsDir, id, 'graph.yml'), change(forkGraph(id, 2.2)));
    };

    // A branch holding a judge node. A fork is judged where its branches converge and nowhere else,
    // so a judge inside one would be judging half a fork on its own.
    await variant('branch-judges', (g) => g.replace(`  - id: read-qor-b
    kind: act
    parameters:
      observes: qorReportB`, `  - id: read-qor-b
    kind: judge
    parameters:
      rules:
        - setup-wns-all-nonnegative
        - clock-period-at-most`));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check branch-judges --site local'),
      /has a judge node, "read-qor-b", inside the branch it forks to "synth-b": a branch is act nodes only, because a fork is judged where its branches converge and nowhere else/,
      'the refusal names the node, the branch it is in, and what a branch may hold',
    );

    // Branches converging into two different nodes. The run waits for every branch at one join, so a
    // fork whose branches end in two places is a run that could never be waited for. Both judge nodes
    // keep two incoming edges — a node with one is a node inside a branch, which is the refusal above
    // — so what this pack gets wrong is the one thing it is about.
    await variant('two-joins', (g) => g
      .replace(`  - id: blocked
    kind: wait`, `  - id: judge-b
    kind: judge
    parameters:
      rules:
        - setup-wns-all-nonnegative
        - clock-period-at-most
      bind:
        target_period_ns: { from: goal, name: target_period_ns }

  - id: read-qor-c
    kind: act
    parameters:
      observes: qorReport

  - id: read-qor-d
    kind: act
    parameters:
      observes: qorReportB

  - id: blocked
    kind: wait`)
      .replace('  - { from: read-qor-b, to: judge }', '  - { from: read-qor-b, to: judge-b }\n  - { from: read-qor-c, to: judge }\n  - { from: read-qor-d, to: judge-b }'));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check two-joins --site local'),
      /has the branches of the fork at "start" converge into two different nodes, "judge" and "judge-b": every branch of one fork reaches one join/,
      'the refusal names the fork and both nodes its branches ended at',
    );

    // An explore node the join leads to. A chooser weighs one reading; a fork leaves one per branch,
    // so a chooser after a join would choose from whichever branch appended last. Two act nodes
    // stand between the join and the explore node, because the rule is about everything the join
    // leads to and not about the node it draws an edge straight to.
    await variant('explores-after-the-join', (g) => g
      .replace(`  - id: blocked
    kind: wait`, `  - id: settle
    kind: act
    parameters:
      observes: qorReport

  - id: next-period
    kind: explore
    parameters:
      chooser: timing-push
      bind:
        guardBandNs: 0.05
      converge:
        read: period
        band: 0.05
        generations: 1
        generationLimit: 6

  - id: blocked
    kind: wait`)
      .replace(`  - { from: read-qor-b, to: judge }`, `  - { from: read-qor-b, to: judge }
  - { from: judge, to: settle, outcome: PASS }
  - { from: settle, to: next-period }
  - { from: next-period, to: start, revisit: true }`));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check explores-after-the-join --site local'),
      /has explore node "next-period" downstream of "judge", the join of the fork at "start": an explore node weighs one reading of its loop's latest generation, and a fork writes one reading per branch, so a chooser standing after a join would choose from whichever branch happened to append last/,
      'the refusal names the explore node, the join it stands after, and what it would have been deciding on',
    );

    // A fork inside a drill-down loop's graph. Fork and drill-down each go one level in step 3.
    await installFork(packsDir, 'fork-in-loop', 2.2);
    await writeFile(path.join(packsDir, 'fork-in-loop', 'graph.yml'), forkInsideALoop('fork-in-loop'));
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check fork-in-loop --site local'),
      /forks at "start" in loop "push": a loop's graph holds no fork, because drill-down and fork each go one level in step 3 and neither is nested in the other/,
      'the refusal names the node, its loop, and why neither nests in the other',
    );
  } finally {
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t);
  if (!local) return;
  const { h, host, dispose } = local;
  let sessions: string[] = [];
  try {
    const started = await himaCommand(
      host,
      h.workspace,
      `/hima run ${timingProbePackId} --site local --goal target_period_ns=2.3 --set periodNs=2.35`,
      siteCommandTimeoutMs,
    );
    assert.equal(started.kind, 'success', started.text);
    const runId = started.runId!;
    sessions = sessionsOf(host, runId);
    const status = await himaCommand(host, h.workspace, `/hima status ${runId}`);
    assert.equal(status.kind, 'success', status.text);
    assert.match(status.text, /generation 2 of at most 6$/m, `the run line says how far in and how far it may go: ${status.text}`);
    assert.match(status.text, /at most 6 generations/, `and the budget line says the allowance: ${status.text}`);

    // A pack that converges on a value its chooser never reads: a Loop that could only ever end at
    // the generation limit, said before a Campaign exists rather than after one.
    await writePackVariant(packsDirOf(h), 'converges-on-nothing', [], [['        read: period', '        read: cell_area']]);
    const checked = await himaCommand(host, h.workspace, '/hima pack check converges-on-nothing --site local');
    assert.equal(checked.kind, 'error', checked.text);
    assert.match(checked.text, /converges on "cell_area", which chooser "over-constraining-push" does not read/, checked.text);
    assert.match(checked.text, /"period", "slack"/, `and says what it does read: ${checked.text}`);

    // A graph that goes back to an act node without saying so: a loop the engine would run and the
    // file would not show. Refused when the pack is *loaded* — before any question about a Site is
    // asked — which is how every other way a pack can contradict itself is refused, and which a
    // person meets as the load's own message rather than as a check that came back unfit.
    await writePackVariant(packsDirOf(h), 'cycles-without-a-revisit', [], [[
      '  - { from: next-period, to: synthesize, revisit: true }',
      '  - { from: next-period, to: synthesize }',
    ]]);
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check cycles-without-a-revisit --site local'),
      /graph\.yml cycles through "synthesize" → "read-qor" → "judge" → "next-period" → "synthesize" without a revisit edge/,
      'the refusal names the cycle it walked and what declares a loop',
    );

    // Two explore nodes, each declaring how many generations a Campaign of this pack may take, and
    // disagreeing: a Run has one Budget, so one of the two numbers would be quietly ignored. Refused
    // where the file can still be read, and for the same reason and in the same way as the cycle.
    await writePackVariant(packsDirOf(h), 'two-generation-limits', [], [[
      '  - id: blocked\n',
      '  - id: second-thoughts\n'
      + '    kind: explore\n'
      + '    parameters:\n'
      + '      chooser: timing-push\n'
      + '      bind:\n'
      + '        guardBandNs: 0.05\n'
      + '      converge:\n'
      + '        read: period\n'
      + '        band: 0.05\n'
      + '        generations: 1\n'
      + '        generationLimit: 3\n'
      + '\n'
      + '  - id: blocked\n',
    ]]);
    await assert.rejects(
      himaCommand(host, h.workspace, '/hima pack check two-generation-limits --site local'),
      /graph\.yml declares 2 different generation limits — 6 on explore node "next-period", 3 on explore node "second-thoughts" — where a campaign has one budget/,
      'the refusal names both numbers and the node each came from',
    );
  } finally {
    killSessions(sessions);
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t);
  if (!local) return;
  const { h, host, dispose } = local;
  let sessions: string[] = [];
  try {
    const started = await himaCommand(
      host,
      h.workspace,
      `/hima run ${timingProbePackId} --site local --goal target_period_ns=2.3 --set periodNs=2.25`,
      siteCommandTimeoutMs,
    );
    assert.equal(started.kind, 'success', started.text);
    const runId = started.runId!;
    sessions = sessionsOf(host, runId);

    // The words table is one function, so what a command prints and what the window renders are one
    // sentence. Anchored to the whole line, because "the goal" said two ways in one answer is what
    // this ticket exists to end.
    const status = await himaCommand(host, h.workspace, `/hima status ${runId}`);
    assert.equal(status.kind, 'success', status.text);
    assert.match(status.text, /^ {2}goal: clock period at most 2\.3 ns$/m, `the goal in the pack's words: ${status.text}`);
    assert.match(status.text, /^ {2}strategy: clock period 2\.25 ns$/m, `and the strategy in the pack's words: ${status.text}`);

    // A word for a name the pack neither takes from its goal nor sets as a strategy knob: a label
    // that could never reach a person, said before a Campaign exists rather than never.
    await writePackVariant(packsDirOf(h), 'words-for-nothing', [[
      '  periodNs: { label: clock period, unit: ns }',
      '  cellAreaUm2: { label: cell area, unit: um2 }',
    ]]);
    const checked = await himaCommand(host, h.workspace, '/hima pack check words-for-nothing --site local');
    assert.equal(checked.kind, 'error', checked.text);
    assert.match(checked.text, /words: declares "cellAreaUm2", which this pack neither takes from its goal nor sets as a strategy knob/, checked.text);
    assert.match(checked.text, /"target_period_ns", "periodNs"/, `and says which names it does use: ${checked.text}`);
  } finally {
    killSessions(sessions);
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t);
  if (!local) return;
  const { h, host, dispose } = local;
  let sessions: string[] = [];
  try {
    const pack = await installTwoKnobs(packsDirOf(h));

    // A value the declaration does not allow is refused before any Campaign exists, in the words the
    // window is refused in: one table, three faces.
    const refused = await himaCommand(host, h.workspace, `/hima run ${pack} --site local --goal target_period_ns=2.0 --set profile=aggressive`);
    assert.equal(refused.kind, 'error', refused.text);
    assert.ok(
      refused.text.includes(badStrategyValue('profile', { type: 'choice', options: ['plain', 'balanced', 'dense'], default: 'plain' }, 'aggressive')),
      `the command says what the shared validator says: ${refused.text}`,
    );
    assert.equal(refused.runId, undefined, `and started nothing: ${refused.text}`);

    // And a knob no pack declares, which is the other half of the same table (#58): a caller setting
    // a knob that is not there is setting nothing, and a Run started for them would have run at the
    // defaults without saying so. Refused in the validator's own sentence, naming what this pack
    // does declare, before any Campaign exists.
    const notAKnob = await himaCommand(host, h.workspace, `/hima run ${pack} --site local --goal target_period_ns=2.0 --set nosuch=1`);
    assert.equal(notAKnob.kind, 'error', notAKnob.text);
    assert.ok(
      notAKnob.text.includes(unknownStrategyKnob('nosuch', ['periodNs', 'profile'])),
      `the command says what the shared validator says: ${notAKnob.text}`,
    );
    assert.equal(notAKnob.runId, undefined, `and started nothing: ${notAKnob.text}`);

    const started = await himaCommand(
      host,
      h.workspace,
      `/hima run ${pack} --site local --goal target_period_ns=2.0 --set periodNs=2.4 --set profile=dense --generations 1`,
      siteCommandTimeoutMs,
    );
    assert.equal(started.kind, 'success', started.text);
    const runId = started.runId!;
    sessions = sessionsOf(host, runId);

    // Both knobs, in the pack's words, on the one line the card says them on: the number with its
    // unit, the choice without one.
    const status = await himaCommand(host, h.workspace, `/hima status ${runId}`);
    assert.equal(status.kind, 'success', status.text);
    assert.match(status.text, /^ {2}strategy: clock period 2\.4 ns, mining profile dense$/m, `the strategy in the pack's words: ${status.text}`);
    assert.match(status.text, /^ {2}decision: .* chose clock period 2\.15 ns, mining profile dense by test-profile-by-outcome/m, `and the decision it chose: ${status.text}`);
  } finally {
    killSessions(sessions);
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t);
  if (!local) return;
  const { h, host, dispose } = local;
  try {
    // Every other rule of the `strategy:` block is in the schema — the bounds hold, the default is
    // inside them, a choice's default is one of its options — and so is this one, because a pack
    // declaring an empty block is a pack whose start form would have nothing on it, whose Explore
    // node would choose between nothing, and whose first Run would otherwise be refused deep in the
    // ledger's own row schema rather than in a sentence about the pack.
    await writePackVariant(packsDirOf(h), 'declares-no-knob', [[shippedStrategyBlock, 'strategy: {}']]);
    // Refused where the contract is read, so it is refused the way every other thing the contract
    // can be wrong about itself is: a pack whose own files do not parse propagates out of the
    // command rather than being answered, because there is no pack there to report on.
    await assert.rejects(
      () => himaCommand(host, h.workspace, '/hima pack check declares-no-knob --site local'),
      /strategy: declares no knob, and a pack whose Strategy has nothing in it has nothing for an Explore node to choose/,
      'the empty block is refused for being empty, and not further down for the chooser and words that then have no knob to name',
    );

    // The shipped pack, unvaried, is the control: the refusal above is about the one thing that was
    // varied and not about a pack that could never have loaded.
    const fits = await himaCommand(host, h.workspace, `/hima pack check ${timingProbePackId} --site local`);
    assert.equal(fits.kind, 'success', fits.text);
  } finally {
    await dispose();
  }
}

async (t) => {
  const local = await localFabric(t);
  if (!local) return;
  const { h, host, dispose } = local;
  try {
    const packsDir = packsDirOf(h);
    await installTwoKnobs(packsDir);

    // A chooser that sets a knob the contract does not declare is a decision the engine could never
    // act on: the value would reach no node, and the Run would go round again at the Strategy that
    // just ran. Said where every other thing a pack can be wrong about a Site is said, and before a
    // licence-minute of synthesis.
    await writePackVariant(packsDir, 'sets-an-undeclared-knob', [[twoKnobStrategyBlock, `strategy:
  periodNs: { type: number, unit: ns, min: 0.5, max: 10, default: 2.40 }`], [twoKnobWordsBlock, shippedWordsBlock]], [], twoKnobPackId);
    const undeclared = await himaCommand(host, h.workspace, '/hima pack check sets-an-undeclared-knob --site local');
    assert.equal(undeclared.kind, 'error', undeclared.text);
    assert.match(undeclared.text, /sets knob "profile" in clause 3, which contract\.yml does not declare; it declares "periodNs"/, undeclared.text);

    // And a knob the contract declares and says no words for: a field on the start form, a line on
    // the card and a column of the ledger that a person would read under the name the wire carries,
    // which for a knob — the pack's own invention — is nothing they could read it as.
    await writePackVariant(packsDir, 'says-nothing-for-a-knob', [[twoKnobWordsBlock, shippedWordsBlock]], [], twoKnobPackId);
    const wordless = await himaCommand(host, h.workspace, '/hima pack check says-nothing-for-a-knob --site local');
    assert.equal(wordless.kind, 'error', wordless.text);
    assert.match(wordless.text, /words: says nothing for strategy knob "profile", which this pack declares/, wordless.text);

    // And that refusal is the gate D47 states, at the face a person starts from: `startRun` runs
    // `checkPack` before anything else it does (`fabric.ts`), so a start of that same pack is
    // refused in the pack check's own sentence and no Run row is written. The start form falls back
    // to the name the wire carries for a knob it has no word for, on purpose — a form that would
    // not render is a worse answer than a name — so this is the assertion that says the fallback is
    // never what a Campaign runs on.
    const startedWordless = await himaCommand(host, h.workspace, '/hima run says-nothing-for-a-knob --site local --goal target_period_ns=2.0');
    assert.equal(startedWordless.kind, 'error', startedWordless.text);
    assert.match(startedWordless.text, /words: says nothing for strategy knob "profile", which this pack declares/, startedWordless.text);
    assert.equal(startedWordless.runId, undefined, `and named no Run: ${startedWordless.text}`);
    assert.deepEqual(host.ctx.hima.ledger.runs(), [], 'no Run row exists: the Campaign was refused before one was opened');

    // A choice knob given a unit is the other half of the same rule: a profile is not measured in
    // anything, and `mining profile dense ns` is what a face would otherwise print.
    await writePackVariant(packsDir, 'measures-a-choice', [[
      '  profile: { label: mining profile }',
      '  profile: { label: mining profile, unit: ns }',
    ]], [], twoKnobPackId);
    const measured = await himaCommand(host, h.workspace, '/hima pack check measures-a-choice --site local');
    assert.equal(measured.kind, 'error', measured.text);
    assert.match(measured.text, /words: gives strategy knob "profile" the unit "ns", and it is a choice of "plain", "balanced", "dense": a choice is measured in nothing/, measured.text);

    // The variant itself, unvaried, fits: the three refusals above are about what was varied and not
    // about a pack that could never have fitted.
    const fits = await himaCommand(host, h.workspace, `/hima pack check ${twoKnobPackId} --site local`);
    assert.equal(fits.kind, 'success', fits.text);
  } finally {
    await dispose();
  }
}
